document.addEventListener('keydown',e=>{
  const el=e.target.closest('[data-region-id]');
  if(el&&['ArrowLeft','ArrowRight','ArrowUp','ArrowDown'].includes(e.key)){
    e.preventDefault();const r=selectedBoard()?.regions?.find(r=>r.id===el.dataset.regionId);if(!r)return;
    const step=e.shiftKey?5:1;r.x=Math.max(0,Math.min(100-r.w,r.x+(e.key==='ArrowLeft'?-step:e.key==='ArrowRight'?step:0)));r.y=Math.max(0,Math.min(100-r.h,r.y+(e.key==='ArrowUp'?-step:e.key==='ArrowDown'?step:0)));persist();render();$(`[data-region-id="${CSS.escape(r.id)}"]`)?.focus();
  }
});

document.addEventListener('click',event=>{const target=event.target.closest('[data-action]');if(!target||target.disabled)return;const action=target.dataset.action,id=target.dataset.id;switch(action){case'home':navigate('home');break;case'navigate':navigate(target.dataset.view);break;case'projects':projectDialog();break;case'open-sample':state.active='alive';section='canvas';persist();navigate('create');break;case'open-project':if(state.projects.some(p=>p.id===id)){state.active=id;persist();closeModal();section='canvas';navigate('create');}break;case'new-project':showDialog('A home for your next idea',`<form class="form" data-form="project"><p>Create a project in this browser’s demo workspace.</p><label for="new-project-name">Project name</label><input id="new-project-name" name="name" maxlength="70" required placeholder="A world worth exploring" autofocus><div class="dialog-actions">${button('close-modal','Cancel')}<button type="submit" class="primary">Create project</button></div></form>`);break;case'create-section':section=target.dataset.section;render();break;case'browse-boards':showDialog('Choose a board',`<div class="project-list">${project().boards.map(b=>`<button data-action="open-board-picker" data-id="${esc(b.id)}">${icon(b.kind==='video'?'video':'image')}<span><strong>${esc(b.name)}</strong><small>${esc(b.profile)}</small></span></button>`).join('')||'<p>No boards yet. Add your first board.</p>'}</div>`);break;case'open-board-picker':selected=id;inspectorTab='board';closeModal();render();break;case'add-board':addBoardDialog();break;case'create-board':{focused=false;const t=target.dataset.type;if(!templates[t])break;const n=project().boards.length,b=board(uid(),`${templates[t].label} ${n+1}`,t,(n%2)*380+50,Math.floor(n/2)*300+50,false);project().boards.push(b);selected=b.id;section='canvas';view='create';inspectorTab='board';camera.fit=false;persist();closeModal();render();note(`Added ${b.name}`);break;}case'select-board':selected=id;inspectorTab='board';render();break;case'close-inspector':selected=null;render();break;case'inspector-tab':inspectorTab=target.dataset.tab;render();break;case'fit':fit();break;case'preview-board':previewBoard(id);break;case'board-media':{const b=project().boards.find(x=>x.id===id);if(b?.ready&&b.asset)showMedia(b.asset);break;}case'media':showMedia(target.dataset.media);break;case'watch-film':showMedia('film');break;case'watch-intro':showMedia('intro');break;case'close-modal':closeModal();break;case'duplicate-board':{const b=project().boards.find(b=>b.id===id);if(!b)break;const copy={...structuredClone(b),id:uid(),name:b.name+' copy',x:b.x+75,y:b.y+65};project().boards.push(copy);selected=copy.id;persist();render();toast('Board duplicated. Drag its header to move it.');break;}case'remove-board':focused=false;project().boards=project().boards.filter(b=>b.id!==id);selected=null;persist();render();toast('Board removed from your demo workspace.');break;case'choose-input':showDialog('Choose a demo starting image',`<p>Pin an explicit image to the video board.</p><div class="media-grid">${['rear','pov'].map(key=>`<button class="media-card" data-action="bind-input" data-media="${key}"><img src="${media[key].src}" alt="${media[key].name}"><div class="copy"><strong>${media[key].name}</strong></div></button>`).join('')}</div>`);break;case'bind-input':{const b=selectedBoard();if(b)b.asset=target.dataset.media==='rear'?'rearVideo':'povVideo';persist();closeModal();render();toast('Starting image selected for this demo board.');break;}case'region':toast(`${target.dataset.region} region selected. This is a composition draft.`);target.parentElement.querySelectorAll('button').forEach(b=>b.classList.remove('active'));target.classList.add('active');break;case'suggest':sendChat(target.dataset.prompt);break;case'new-chat':showDialog('Start a fresh demo chat?',`<p>Your saved ideas and boards stay in place. This clears the current prepared conversation.</p><div class="dialog-actions">${button('close-modal','Keep chatting')}${button('confirm-new-chat','New chat','primary')}</div>`);break;case'confirm-new-chat':chatToken++;replyBusy=false;project().messages=[];persist();closeModal();render();break;case'message-to-board':{const m=project().messages.find(m=>m.id===id);if(m)chooseDestination(m.prompt||m.text,m.title);break;}case'save-idea':{const m=project().messages.find(m=>m.id===id);if(!m)break;project().ideas.unshift({id:uid(),title:m.title||'A new idea',text:m.prompt||m.text});persist();toast('Idea saved in Create → Ideas.');break;}case'copy-message':{const m=project().messages.find(m=>m.id===id);if(m)navigator.clipboard?.writeText(m.prompt||m.text).then(()=>toast('Copied.')).catch(()=>toast('Select the reply text to copy it.'));break;}case'idea-to-board':{const idea=project().ideas.find(i=>i.id===id);if(idea)chooseDestination(idea.text,idea.title);break;}case'delete-idea':project().ideas=project().ideas.filter(i=>i.id!==id);persist();render();break;case'fullscreen-chat':liveOpen('chat');break;case'voice':liveOpen('voice');break;case'live-mode':stopVoice();liveMode=target.dataset.mode;renderLive();break;case'close-live':stopVoice();live.close();break;case'play-voice':void playVoice();break;case'stop-voice':stopVoice();break;case'settings':navigate('settings');break;case'theme':state.theme=target.dataset.theme;persist();render();break;case'activity':showDialog('Demo activity',`<p>A view of actions in this browser, not a backend console.</p><div class="activity-list">${state.activity.length?state.activity.map(a=>`<div class="activity-item">${icon('check')}<div><strong>${esc(a.text)}</strong><small>Browser-only demo action</small></div></div>`).join(''):'<div class="notice">Explore the Canvas to start your demo activity.</div>'}</div>`);break;case'jobs':jobsDialog();break;case'reset':showDialog('Reset this demo?',`<p>This removes this site’s local demo edits and restores the original sample. It does not touch the installed Darius app.</p><div class="dialog-actions">${button('close-modal','Keep exploring')}${button('confirm-reset','Reset demo','primary')}</div>`);break;case'confirm-reset':focused=false;regionId=null;sessionToken++;chatToken++;replyBusy=false;jobTimers.forEach(clearTimeout);jobTimers=[];stopVoice();state=initial();persist();closeModal();if(live.open)live.close();view='home';selected=null;camera.fit=false;render();toast('The original demo is restored.');break;case'timeline-clip':editIndex=Math.max(0,Math.min(timeline.length-1,Number(target.dataset.index)||0));render();break;case'about':showDialog('Make yourself at home',`<p>This is a static, interactive Darius showcase. Try these things:</p><div class="activity-list"><div class="activity-item">${icon('layers')}<div><strong>Make the Canvas yours</strong><p>Move boards, zoom, pan, duplicate a board and edit a prompt.</p></div></div><div class="activity-item">${icon('talk')}<div><strong>Follow an idea</strong><p>Try the guided chat, save an idea and apply a prompt to a board.</p></div></div><div class="activity-item">${icon('mic')}<div><strong>Hear a conversation</strong><p>Play the recorded fullscreen voice session from the actual demo project.</p></div></div></div><div class="notice">Prepared examples are labelled throughout. Generation and live AI need the full app; no backend, credentials, microphone or paid services are connected here.</div>`);break;}});
document.addEventListener('input',e=>{const field=e.target.dataset.field;if(field){const b=selectedBoard();if(!b)return;b[field]=field==='seconds'?Number(e.target.value):e.target.value;persist();if(field==='name'){const focusedHeading=$('.focused-heading h2');if(focusedHeading)focusedHeading.textContent=b.name;const heading=$(`.board-card[data-board="${CSS.escape(b.id)}"] strong`);if(heading)heading.textContent=b.name;}}});
document.addEventListener('change',e=>{if(e.target.id==='board-ratio'){persist();if(focused)render();}if(e.target.id==='fibo-preset'){const b=selectedBoard();if(b){b.profile=e.target.value==='turbo'?'FIBO · Fast preview · Turbo':'FIBO · Dev render';persist();render();}}if(e.target.id==='reduced-motion'){state.reduced=e.target.checked;persist();render();}});
document.addEventListener('submit',e=>{const type=e.target.dataset.form;if(!type)return;e.preventDefault();const data=new FormData(e.target);if(type==='chat'){sendChat(String(data.get('message')||''));}if(type==='project'){const name=String(data.get('name')||'').trim();if(!name)return;const p={id:uid(),name:name.slice(0,70),description:'A browser-only demo project.',boards:[],messages:[],ideas:[]};state.projects.push(p);state.active=p.id;focused=false;section='canvas';view='create';camera.fit=false;persist();closeModal();render();toast('Your demo project is ready.');}if(type==='handoff'){const b=project().boards.find(b=>b.id===data.get('board'));if(!b)return;b.prompt=String(data.get('prompt')||'').slice(0,6000);selected=b.id;focused=false;view='create';section='canvas';inspectorTab='board';camera.fit=false;persist();closeModal();if(live.open){stopVoice();live.close();}render();note(`Applied a reviewed prompt to ${b.name}`);toast('Prompt applied. Previewing is a separate action.');}});
document.addEventListener('keydown',e=>{if(e.target.matches('textarea[name=message]')&&e.key==='Enter'&&!e.shiftKey&&!e.isComposing){e.preventDefault();e.target.closest('form').requestSubmit();}});
modal.addEventListener('click',e=>{if(e.target===modal){const r=modal.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)closeModal();}});
